INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_111', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-1-1' AND is_deleted = false LIMIT 1), 'copies-references-const-quiz', 'Copies, references and what compiles', 'Read each snippet the way the compiler does: which names are copies, which are aliases, and which initializations and assignments the language accepts.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_111'), 'What does this program print? (std::println prints a vector of double as [a, b, c], and 6.0 as 6.)

#include <print>
#include <vector>

void bump(double s) { s += 1.0; }
void bump_ref(double& s) { s += 1.0; }

int main() {
    std::vector<double> v{5.0, 6.0, 7.0};
    for (auto s : v) s += 1.0;
    bump(v[0]);
    bump_ref(v[1]);
    auto x = v[2];
    x += 1.0;
    auto& y = v[2];
    y += 0.5;
    std::println("{}", v);
}', 'single_choice'::question_type, 'for (auto s : v) gives s a copy of each element, so the loop changes three copies and v stays [5, 6, 7]. bump takes its parameter by value: it changes a copy of v[0], so v[0] stays 5. bump_ref takes double&, so s is another name for v[1] and v[1] becomes 7. auto x = v[2] deduces double (auto drops the reference), so x is a copy and x += 1.0 does not touch v. auto& y = v[2] is an alias, so y += 0.5 makes v[2] 7.5. Result: [5, 7, 7.5]. [6, 7, 8] would need the range-for to change the elements; [5, 6, 7] ignores that bump_ref and y are references; [5, 7, 8.5] treats auto x as a reference; [6, 8, 8.5] treats every name as a reference.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[5, 6, 7]', false),
        ('[5, 7, 7.5]', true),
        ('[5, 7, 8.5]', false),
        ('[6, 7, 8]', false),
        ('[6, 8, 8.5]', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_111'), 'Each option is a complete small program compiled with g++ -std=c++23 -Wall -Wextra. Which of them compile? (Select all that apply.)', 'multiple_choice'::question_type, 'int seats = 39.9; compiles: copy initialization with = silently converts the double and seats is 39 (no warning under -Wall -Wextra; -Wconversion would warn). long long total{count}; compiles: int to long long is a widening conversion, every int value fits, so braces accept it. int avg{7.75}; is rejected: braces refuse a narrowing conversion, and g++ reports error: narrowing conversion of ''7.75e+0'' from ''double'' to ''int''. Assigning v[0] = 0.0 through a const std::vector<double>& is an error (assignment of read-only location): const& promises the function will not change the caller''s data. add_bonus(9.0, 0.5) with a double& parameter is an error (cannot bind non-const lvalue reference of type ''double&'' to an rvalue of type ''double''): a non-const reference must refer to an existing object it can change, and 9.0 is a temporary.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('int main() { int seats = 39.9; return seats; }', true),
        ('int main() { int count = 32; long long total{count}; return static_cast<int>(total); }', true),
        ('int main() { int avg{7.75}; return avg; }', false),
        ('#include <vector>
void reset(const std::vector<double>& v) { v[0] = 0.0; }
int main() { std::vector<double> s{1.0}; reset(s); }', false),
        ('void add_bonus(double& s, double b) { s += b; }
int main() { add_bonus(9.0, 0.5); }', false)
    ) AS o(option_text, is_correct);

