-- challenge chal_quiz_cppf_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_131', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-1-3' AND is_deleted = false LIMIT 1), 'reading-input-quiz', 'Predict what std::cin reads', 'Follow the read position through the input buffer: what does each read consume, what does it leave behind, and when does the loop really stop?', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_131'), 'The program gets exactly this input (two lines, each ending with a newline):

RP-01 An
RP-02 Bình

What does it print?

std::string id, name;
int records = 0;
while (!std::cin.eof()) {
    std::cin >> id;
    std::getline(std::cin, name);
    ++records;
}
std::println("{} [{}] [{}]", records, id, name);', 'single_choice'::question_type, 'Round 1: >> reads RP-01 and stops at the space, getline reads the rest of the line, " An" WITH its leading space, and eats the newline. Round 2 does the same for RP-02 and " Bình". Now every character has been read, but eof() is still false: getline stopped at the newline and never tried to read past it. So the loop runs a third time. This time >> finds the end of input, sets eofbit and failbit, and leaves id unchanged; getline on a failed stream does nothing, so name is unchanged too. records is 3, id is RP-02, name is " Bình". "2 ..." would be right only for while (std::cin >> id && std::getline(std::cin, name)). "[Bình]" without the space forgets that getline keeps the space after the id (only >> std::ws would remove it). "3 [] []" assumes a failed read clears the strings - it does not, the variables keep their last values.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_131') AND order_index = 1)
    RETURNING id
)
