    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_131'), 'Each line of a score file looks like "RP-01 8.5 Trần Văn An" and the file ends with a newline. Which loops call handle(line) exactly once per line, with the whole line, and stop after the last one? (Select all that apply.) Assume std::string line; is declared before each loop where needed.', 'multiple_choice'::question_type, 'A loop is correct when the read itself is the loop condition: the body runs only after a read that succeeded. while (std::getline(std::cin, line)) and the for form (which also keeps line local to the loop) do that - in a real run on two lines they called handle twice. while (!std::cin.eof()) and while (std::cin) test the stream BEFORE the read: after the last line both are still true, getline then fails at the end of input and leaves line empty, and handle is called a third time with "". while (std::cin >> line) checks its read, but >> reads one word, not one line: on the two-line file it called handle 9 times, with RP-01, 8.5, Trần, Văn, An and so on.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('while (!std::cin.eof()) { std::getline(std::cin, line); handle(line); }', false),
        ('while (std::getline(std::cin, line)) { handle(line); }', true),
        ('while (std::cin) { std::getline(std::cin, line); handle(line); }', false),
        ('for (std::string line; std::getline(std::cin, line); ) { handle(line); }', true),
        ('while (std::cin >> line) { handle(line); }', false)
    ) AS o(option_text, is_correct);

