-- challenge chal_quiz_cppf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_211', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-2-1' AND is_deleted = false LIMIT 1), 'pass-by-value-reference-overloads-quiz', 'Predict it: copies, references and overloads', 'Read each call the way the compiler does: which object does the function work on, and which overload does the argument match best?', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_211'), 'What does this program print?

#include <print>
#include <vector>

void a(std::vector<int> v)             { v.push_back(1); }
void b(std::vector<int>& v)            { v.push_back(2); }
std::vector<int> c(std::vector<int> v) { v.push_back(3); return v; }
void d(const std::vector<int>& v)      { auto copy = v; copy.push_back(4); }

int main() {
    std::vector<int> s;
    a(s);
    b(s);
    c(s);
    d(s);
    std::vector<int> t = c(s);
    b(s);
    std::println("{} {}", s, t);
}', 'single_choice'::question_type, 'Only b takes a reference, so only b changes s. a works on its own copy, and the copy is destroyed when a returns. c also works on a copy and returns it, but the first call c(s) throws the result away, so nothing is kept. d can only read v; it pushes onto a local copy that disappears. So after b(s) s is [2]; t = c(s) is a copy of [2] with 3 added, [2, 3]; the last b(s) makes s [2, 2]. Output: [2, 2] [2, 3]. "[1, 2, 3, 4, 3, 2] [1, 2, 3, 4, 3]" would be the output if every function took a reference. "[2, 3, 2] [2, 3, 3]" assumes the ignored c(s) changed s - returning a value never changes the argument; the caller has to assign it. "[2, 4, 2] [2, 4, 3]" assumes d''s local copy is the caller''s vector. "[2, 2] [2, 2, 3]" computes t after the last b(s), but statements run in order: t was made when s was [2].', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_211') AND order_index = 1)
    RETURNING id
)
