SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[2, 2] [2, 3]', true),
        ('[1, 2, 3, 4, 3, 2] [1, 2, 3, 4, 3]', false),
        ('[2, 3, 2] [2, 3, 3]', false),
        ('[2, 4, 2] [2, 4, 3]', false),
        ('[2, 2] [2, 2, 3]', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_211'), 'The score tool has two overloads:

void round_score(int points);     // 0-100 points
void round_score(double score);   // 0-10 scale

Which of these calls compile AND call the double overload? (Select all that apply.)', 'multiple_choice'::question_type, 'The compiler ranks each overload by how the argument converts: an exact match beats a promotion, and a promotion beats a conversion. round_score(7.5f): float to double is a floating-point promotion, float to int only a conversion, so the double overload wins. round_score(0.5 * 17): the expression is a double (8.5), an exact match for double. round_score(''9''): char to int is an integral promotion, so the int overload is called with 57, the character code of ''9'' - it compiles and silently picks int. round_score(17 / 2): both operands are int, so this is integer division; the argument is the int 8 and the int overload is an exact match. round_score(8L): long to int and long to double are both conversions of the same rank, so neither is better and g++ stops with "call of overloaded ''round_score(long int)'' is ambiguous" - it does not compile.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('round_score(7.5f)', true),
        ('round_score(''9'')', false),
        ('round_score(0.5 * 17)', true),
        ('round_score(17 / 2)', false),
        ('round_score(8L)', false)
    ) AS o(option_text, is_correct);

