INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_cppf_221', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-2-2' AND is_deleted = false LIMIT 1), 'section-with-waitlist', 'Write a Section class that never overfills', 'The ported enrolment tool lets any code path change a section''s numbers, and CS101-02 ended up with 47 students in a 40-seat lab. Write a Section class whose private data can only change through its member functions: the constructor rejects a capacity that is not positive with std::invalid_argument("capacity must be > 0"); enroll(id) returns "enrolled" while there is a free seat, "waitlisted" when the section is full, and "duplicate" if the student is already enrolled or already waiting; drop(id) frees the seat and moves the first waitlisted student into it ("dropped, promoted <id>"), or returns "dropped", "left waitlist" or "not found". The test runner reads the section and a list of commands from stdin, prints the result of each command and then the final summary() through a const reference.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
