-- challenge chal_quiz_cppf_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_231', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-2-3' AND is_deleted = false LIMIT 1), 'lifetime-and-dangling-quiz', 'Predict it: destructor order and dangling references', 'Read each snippet the way C++ runs it: when does each object die, and does anything still point at it afterwards?', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_231'), 'What does this program print?

#include <print>

struct T {
    char c;
    T(char x) : c(x) { std::print("+{} ", c); }
    ~T() { std::print("-{} ", c); }
};

void f(bool early) {
    T x(''x'');
    if (early) return;
    T y(''y'');
}

int main() {
    T a(''a'');
    {
        T b(''b'');
        f(true);
    }
    f(false);
}', 'single_choice'::question_type, 'An automatic object is destroyed when control leaves its scope, and objects in the same scope die in reverse order of construction. a is built first. Inside the block, b is built, then f(true) builds x and returns early: y was never constructed, so only x is destroyed (-x). The closing brace of the block destroys b (-b). f(false) builds x, then y, and at its closing brace destroys them in reverse order: -y, then -x. Finally main ends and a dies (-a). So the output is +a +b +x -x -b +x +y -y -x -a. The option with -x -y has the order of y and x the wrong way round (that would be construction order, not reverse). The option where b lives until the end of main ignores the block''s closing brace. The option with -y after the early return destroys an object that was never constructed - an early return only destroys what was already built.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('+a +b +x -x -b +x +y -y -x -a', true),
        ('+a +b +x -x -b +x +y -x -y -a', false),
        ('+a +b +x -x +x +y -y -x -b -a', false),
        ('+a +b +x -y -x -b +x +y -y -x -a', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_231'), 'Each line in main uses the function above it. Which of them leave name referring to an object that is already dead? (Select all that apply.)

A)  std::string make_id(int n) { return "RP-2024-" + std::to_string(n); }
    std::string name = make_id(137);

B)  const std::string& banner() { std::string b = "Riverside Polytechnic"; return b; }
    const std::string& name = banner();

C)  std::string make_id(int n) { return "RP-2024-" + std::to_string(n); }
    std::string_view name = make_id(137);

D)  std::string_view course_code() { return "CS101"; }
    std::string_view name = course_code();

E)  std::string make_id(int n) { return "RP-2024-" + std::to_string(n); }
    const std::string& name = make_id(137);', 'multiple_choice'::question_type, 'A returns a std::string by value: name is its own object and owns its characters, so nothing dangles. B returns a reference to the local b, which is destroyed when banner() returns - name refers to a dead string (g++ warns with -Wreturn-local-addr, and reading it is undefined behaviour). C stores a std::string_view, which only points at characters it does not own; the temporary std::string returned by make_id is destroyed at the end of the full expression (the semicolon), so the view points at characters of a dead object (AddressSanitizer reports stack-use-after-scope here, because a string this short keeps its characters inside the std::string object itself; a longer one gives heap-use-after-free). D is fine: a string literal like "CS101" lives for the whole program, so a view of it never dangles. E is fine too, which surprises many people: binding a temporary directly to a const reference extends the temporary''s lifetime to the lifetime of the reference. That rule applies only to a temporary bound directly - it does not apply to B, where the function returns a reference to a local, nor to a std::string_view as in C.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A) std::string name = make_id(137);', false),
        ('B) const std::string& name = banner();', true),
        ('C) std::string_view name = make_id(137);', true),
        ('D) std::string_view name = course_code();', false),
        ('E) const std::string& name = make_id(137);', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_cppf_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
