-- challenge chal_quiz_cppf_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_321', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-3-2' AND is_deleted = false LIMIT 1), 'map-lookup-and-container-choice-quiz', 'Predict the output: lookups that insert, and picking a container', 'Read each snippet the way the standard library runs it: which calls add a key, which only look, and which container fits the job.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_321'), 'With #include <map>, <print>, <stdexcept> and <string>, what does this print?

std::map<std::string, int> seats{{"CS101", 40}, {"CS102", 35}};
if (seats["CS103"] > 0) std::println("CS103 open");
if (seats.contains("CS104")) std::println("CS104 open");
if (seats.find("CS105") != seats.end()) std::println("CS105 open");
std::println("size {}", seats.size());
try {
    std::println("{}", seats.at("CS106"));
} catch (const std::out_of_range& e) {
    std::println("error: {}", e.what());
}
std::println("size {}", seats.size());', 'single_choice'::question_type, 'seats["CS103"] does not find CS103, so operator[] inserts it with int{} = 0 and returns a reference to that 0. 0 > 0 is false, so "CS103 open" is not printed - but the map now has 3 entries. contains() and find() only look: they never insert, so CS104 and CS105 are not added and nothing is printed for them. size is 3. at("CS106") does not insert either: for a missing key it throws std::out_of_range, and with GCC''s standard library what() is "map::at". After the catch the size is still 3. "size 2 ... size 2" assumes operator[] only reads, as in Python or JavaScript - not in C++. "size 5 ... size 6" treats every lookup, and at(), as an insert. "CS103 open ... 0 ... size 4" would need the inserted value to be above 0 and at() to return a default value and insert it; it does neither. Nothing here fails to compile: the map is not const, so operator[] is allowed, and it is allowed for missing keys - that is exactly when it inserts.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('size 2, then error: map::at, then size 2', false),
        ('size 3, then error: map::at, then size 3', true),
        ('size 5, then error: map::at, then size 6', false),
        ('CS103 open, then size 3, then 0, then size 4', false),
        ('It does not compile: seats["CS103"] is not allowed for a key that is missing', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_321'), 'The exam office ports its attendance tools to C++23. Which of these choices are correct? (Select all that apply.)', 'multiple_choice'::question_type, 'std::map keeps its keys sorted (a balanced tree, O(log n) per lookup), so iterating it prints the class list in id order with no sort step. std::unordered_set is a hash set with average O(1) insert and lookup, which fits a "seen already?" check where order does not matter. The iteration order of std::unordered_map is unspecified: it depends on the hash function and the number of buckets, so it can change after more inserts or a rehash, or with another library version - in a GCC 15 run, the same five ids came out in a different order after rehash(64). A stable export needs std::map, or a copy that you sort. operator[] is a non-const member function because it may insert: calling it on a const std::map& does not compile (GCC: "passing ‘const std::map<...>’ as ‘this’ argument discards qualifiers"); use find(), contains() or at() instead. For counting, inserting 0 for a new key is exactly what you want, so ++counts[id] is the idiomatic way to count in either kind of map.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('To print the class list sorted by student id with no separate sort step, keep it in a std::map<std::string, int>.', true),
        ('To check whether a card was already scanned in this session, with no order needed, use a std::unordered_set<std::string>.', true),
        ('Iterating the same std::unordered_map always gives the same order in one program, so the nightly CSV export can rely on it.', false),
        ('A report function that takes const std::map<std::string, int>& attendance can return attendance[id]: for an unknown id it returns 0 and leaves the map unchanged.', false),
        ('Counting check-ins per student with ++counts[id] is a correct use of operator[]: inserting 0 for a new id is what counting needs.', true)
    ) AS o(option_text, is_correct);

