-- challenge chal_quiz_cppf_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cppf_411', (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'cpp-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cppf-4-1' AND is_deleted = false LIMIT 1), 'iterator-invalidation-quiz', 'Predict it: erase loops and stale iterators', 'Run an erase loop in your head, then decide which operations leave a saved iterator pointing at nothing.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_411'), 'The exam office removes every result below 50 points with the loop ported from C. What does this program print?

std::vector<int> points = {45, 30, 75, 20, 15, 90};
for (std::size_t i = 0; i < points.size(); ++i)
    if (points[i] < 50)
        points.erase(points.begin() + i);
for (int p : points) std::print("{} ", p);', 'single_choice'::question_type, 'Step through it. i = 0: 45 is below 50 and is erased, everything moves one slot left ({30, 75, 20, 15, 90}), then ++i makes i = 1 - so 30, which now sits in slot 0, is never checked. i = 1: 75 stays. i = 2: 20 is erased ({30, 75, 15, 90}) and 15 slides into slot 2, which is skipped by ++i. i = 3: 90 stays, and i = 4 ends the loop. The result is 30 75 15 90: two results below 50 survive, each one right after an erased element. "75 90" is what the loop was meant to do. "30 75 90" and "75 15 90" each skip only one of the two survivors. The behaviour is not undefined: i is compared with the current size() on every pass, so every access is in range - the program is wrong, but deterministically wrong, which is exactly why it passed review.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('75 90', false),
        ('30 75 15 90', true),
        ('30 75 90', false),
        ('75 15 90', false),
        ('The behaviour is undefined: it may print anything or crash', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_411'), 'roster is a std::vector<Student> with size() == 4 and capacity() == 4, and by_id is a std::map<std::string, Student> with one entry. The code saves two iterators:

auto first = roster.begin();
auto found = by_id.find("RP-2024-0101");

Then ONE of the operations below runs. After which of them is it undefined behaviour to use the saved iterator (first for the vector operations, found for the map)? (Select all that apply.)', 'multiple_choice'::question_type, 'push_back on a full vector (size == capacity) must allocate a bigger buffer, move the elements there and free the old one, so every iterator, pointer and reference into the vector is invalidated - _GLIBCXX_DEBUG reports "attempt to dereference a singular iterator" when first is used. erase(roster.begin()) invalidates the erased position and everything after it, and first IS the erased position. reserve(100) asks for more capacity than the vector has, which also reallocates and invalidates everything. pop_back() only invalidates the last element and end(); first, at position 0, stays valid and still refers to the first student. A std::map never moves its elements: insert invalidates no iterator, so found still refers to RP-2024-0101 (erase would invalidate only the erased element).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cppf_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('roster.push_back(late_student);', true),
        ('roster.erase(roster.begin());', true),
        ('roster.pop_back();', false),
        ('roster.reserve(100);', true),
        ('by_id.insert({"RP-2024-0137", bich});  (using found afterwards)', false)
    ) AS o(option_text, is_correct);

